import { randomUUID } from 'node:crypto';
import { Router } from 'express';
import { z } from 'zod';
import { errorHandler } from '../lib/errors.ts';
import { idempotency } from '../lib/idempotency.ts';
import { CursorQuerySchema, pageSchema, paginate } from '../lib/pagination.ts';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';

const UserRoleSchema = z.enum(['admin', 'member']);

const UserSchema = z.object({
  id: z.uuid(),
  createdAt: z.iso.datetime(),
  updatedAt: z.iso.datetime(),
  email: z.email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
});

type User = z.infer<typeof UserSchema>;

const CreateUserBodySchema = z.object({
  email: z.email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema.default('member'),
});

const UpdateUserBodySchema = z
  .object({
    email: z.email().optional(),
    name: z.string().min(1).max(100).optional(),
    role: UserRoleSchema.optional(),
  })
  .refine((body) => Object.keys(body).length > 0, {
    message: 'At least one field must be provided',
  });

const UserParamsSchema = z.object({ userId: z.uuid() });
const UsersPageSchema = pageSchema(UserSchema);

function userCursorKey(user: User): string {
  return `${user.createdAt}|${user.id}`;
}

export function registerRoutes(app: Router): void {
  const users = new Map<string, User>();

  app.get('/v1/users', (req, res) => {
    const query = CursorQuerySchema.parse(req.query);
    const page = paginate([...users.values()], query, userCursorKey);
    res.json(UsersPageSchema.parse(page));
  });

  app.post('/v1/users', idempotency(), (req, res) => {
    const body = CreateUserBodySchema.parse(req.body);
    if ([...users.values()].some((user) => user.email === body.email)) {
      throw conflict('email: A user with this email already exists.', 'duplicate-email');
    }

    const now = new Date().toISOString();
    const user = UserSchema.parse({
      id: randomUUID(),
      createdAt: now,
      updatedAt: now,
      email: body.email,
      name: body.name,
      role: body.role,
    });
    users.set(user.id, user);
    res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user));
  });

  app.get('/v1/users/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const user = users.get(userId);
    if (user === undefined) {
      throw notFound('userId: User not found.');
    }
    res.json(UserSchema.parse(user));
  });

  app.patch('/v1/users/:userId', idempotency(), (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const body = UpdateUserBodySchema.parse(req.body);
    const user = users.get(userId);
    if (user === undefined) {
      throw notFound('userId: User not found.');
    }

    if (
      body.email !== undefined &&
      [...users.values()].some((other) => other.id !== userId && other.email === body.email)
    ) {
      throw conflict('email: A user with this email already exists.', 'duplicate-email');
    }

    const updated = UserSchema.parse({
      ...user,
      ...body,
      updatedAt: new Date().toISOString(),
    });
    users.set(userId, updated);
    res.json(UserSchema.parse(updated));
  });

  app.delete('/v1/users/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    if (!users.has(userId)) {
      throw notFound('userId: User not found.');
    }
    users.delete(userId);
    res.status(204).end();
  });

  app.use(errorHandler);
}

