app.get('/v1/users', (req, res) => {
  const limitResult = z.coerce.number().int().min(1).max(100).safeParse(req.query.limit);
  const cursorResult = z.string().min(1).safeParse(req.query.cursor);

  const queryResult = CursorQuerySchema.safeParse(req.query);
  if (!queryResult.success || !limitResult.success || (req.query.cursor !== undefined && !cursorResult.success)) {
    const details: string[] = [];

    if (!limitResult.success) {
      details.push(`limit: ${limitResult.error.issues[0]?.message ?? 'Invalid input'}`);
    }
    if (req.query.cursor !== undefined && !cursorResult.success) {
      details.push(`cursor: ${cursorResult.error.issues[0]?.message ?? 'Invalid input'}`);
    }
    if (details.length === 0) {
      details.push(
        ...queryResult.error.issues.map((issue) => `${issue.path.join('.')}: ${issue.message}`),
      );
    }
    throw unprocessable(details.join('; '));
